#!/usr/bin/env python3
"""
Install NDRT website avatar, page sharing, PWA support and a standard footer.

Safe usage from the repository root:

    python3 install_ndrt_features.py --dry-run
    python3 install_ndrt_features.py

No pip packages are required.
"""

from __future__ import annotations

import argparse
import base64
import json
import re
import shutil
import sys
from datetime import datetime
from pathlib import Path

HEAD_START = "<!-- NDRT FEATURES START -->"
HEAD_END = "<!-- NDRT FEATURES END -->"
FOOTER_START = "<!-- NDRT STANDARD FOOTER START -->"
FOOTER_END = "<!-- NDRT STANDARD FOOTER END -->"

IGNORED_PARTS = {
    ".git",
    ".ndrt_feature_backup",
    "__pycache__",
    "node_modules",
}

ICON_DATA = {'favicon-32.png': '', 'apple-touch-icon.png': '', 'icon-192.png': '', 'icon-512.png': '', 'maskable-512.png': ''}
MANIFEST_TEXT = '{\n  "id": "./",\n  "name": "Nanny-Delvin Rivers Trust",\n  "short_name": "Nanny-Delvin",\n  "description": "Community-led catchment restoration, stewardship and catchment intelligence for the Nanny-Delvin system.",\n  "start_url": "./index.html",\n  "scope": "./",\n  "display": "standalone",\n  "background_color": "#F6FAF8",\n  "theme_color": "#0F5E46",\n  "orientation": "any",\n  "icons": [\n    {\n      "src": "assets/icons/icon-192.png",\n      "sizes": "192x192",\n      "type": "image/png",\n      "purpose": "any"\n    },\n    {\n      "src": "assets/icons/icon-512.png",\n      "sizes": "512x512",\n      "type": "image/png",\n      "purpose": "any"\n    },\n    {\n      "src": "assets/icons/maskable-512.png",\n      "sizes": "512x512",\n      "type": "image/png",\n      "purpose": "maskable"\n    }\n  ]\n}\n'
SERVICE_WORKER_TEXT = 'const CACHE_NAME = "ndrt-site-v1";\nconst BASE = self.registration.scope;\n\nconst CORE_PATHS = [\n  "",\n  "index.html",\n  "citizen-science.html",\n  "privacy.html",\n  "accessibility.html",\n  "news/",\n  "manifest.webmanifest",\n  "assets/css/ndrt.css",\n  "assets/css/site-tools.css",\n  "assets/js/site-tools.js",\n  "assets/icons/favicon-32.png",\n  "assets/icons/apple-touch-icon.png",\n  "assets/icons/icon-192.png",\n  "assets/icons/icon-512.png",\n  "assets/icons/maskable-512.png"\n];\n\nconst CORE_URLS = CORE_PATHS.map((path) => new URL(path, BASE).href);\n\nself.addEventListener("install", (event) => {\n  event.waitUntil(\n    caches.open(CACHE_NAME).then(async (cache) => {\n      await Promise.allSettled(\n        CORE_URLS.map((url) =>\n          cache.add(new Request(url, { cache: "reload" }))\n        )\n      );\n    })\n  );\n  self.skipWaiting();\n});\n\nself.addEventListener("activate", (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) =>\n      Promise.all(\n        keys\n          .filter((key) => key !== CACHE_NAME)\n          .map((key) => caches.delete(key))\n      )\n    )\n  );\n  self.clients.claim();\n});\n\nself.addEventListener("fetch", (event) => {\n  const request = event.request;\n\n  if (request.method !== "GET") return;\n\n  const requestUrl = new URL(request.url);\n  const scopeUrl = new URL(BASE);\n\n  if (requestUrl.origin !== scopeUrl.origin) return;\n\n  if (request.mode === "navigate") {\n    event.respondWith(\n      fetch(request)\n        .then((response) => {\n          const copy = response.clone();\n          caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));\n          return response;\n        })\n        .catch(async () => {\n          return (\n            (await caches.match(request)) ||\n            (await caches.match(new URL("index.html", BASE).href))\n          );\n        })\n    );\n    return;\n  }\n\n  event.respondWith(\n    caches.match(request).then((cached) => {\n      if (cached) return cached;\n\n      return fetch(request).then((response) => {\n        if (response && response.ok) {\n          const copy = response.clone();\n          caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));\n        }\n        return response;\n      });\n    })\n  );\n});\n'
SITE_TOOLS_JS = '(() => {\n  "use strict";\n\n  const script =\n    document.currentScript ||\n    [...document.scripts].find((item) =>\n      item.src.includes("site-tools.js")\n    );\n\n  if (!script) return;\n\n  const scriptUrl = new URL(script.src, document.baseURI);\n  const siteRoot = new URL("../../", scriptUrl);\n  const asset = (path) => new URL(path, siteRoot).href;\n\n  const isStandalone =\n    window.matchMedia("(display-mode: standalone)").matches ||\n    window.navigator.standalone === true;\n\n  const isIOS =\n    /iphone|ipad|ipod/i.test(navigator.userAgent) ||\n    (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);\n\n  let deferredPrompt = null;\n\n  function pageDescription() {\n    const meta = document.querySelector(\'meta[name="description"]\');\n    return meta?.content?.trim() || "Nanny-Delvin Rivers Trust";\n  }\n\n  function showToast(message) {\n    let toast = document.querySelector(".site-toast");\n\n    if (!toast) {\n      toast = document.createElement("div");\n      toast.className = "site-toast";\n      toast.setAttribute("role", "status");\n      toast.setAttribute("aria-live", "polite");\n      document.body.appendChild(toast);\n    }\n\n    toast.textContent = message;\n    toast.classList.add("is-visible");\n\n    clearTimeout(showToast.timeout);\n    showToast.timeout = setTimeout(() => {\n      toast.classList.remove("is-visible");\n    }, 3000);\n  }\n\n  function shareIcon() {\n    return `\n      <svg viewBox="0 0 24 24" aria-hidden="true">\n        <path d="M18 8a3 3 0 1 0-2.83-4 3 3 0 0 0 .08 1.02L8.91 8.2a3 3 0 0 0-4.66 2.5 3 3 0 0 0 4.66 2.5l6.34 3.18A3 3 0 1 0 16.1 14.6l-6.34-3.17a3.1 3.1 0 0 0 0-.86l6.34-3.17A3 3 0 0 0 18 8Z"/>\n      </svg>`;\n  }\n\n  function installIcon() {\n    return `\n      <svg viewBox="0 0 24 24" aria-hidden="true">\n        <path d="M12 3a1 1 0 0 1 1 1v8.59l2.3-2.3a1 1 0 1 1 1.4 1.42l-4 4a1 1 0 0 1-1.4 0l-4-4a1 1 0 1 1 1.4-1.42l2.3 2.3V4a1 1 0 0 1 1-1Zm-7 14a1 1 0 0 1 1 1v1h12v-1a1 1 0 1 1 2 0v2a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-2a1 1 0 0 1 1-1Z"/>\n      </svg>`;\n  }\n\n  function showIOSInstructions() {\n    let dialog = document.querySelector("#ios-install-dialog");\n\n    if (!dialog) {\n      dialog = document.createElement("dialog");\n      dialog.id = "ios-install-dialog";\n      dialog.className = "site-dialog";\n      dialog.innerHTML = `\n        <div class="site-dialog-inner">\n          <button\n            class="site-dialog-close"\n            type="button"\n            aria-label="Close"\n          >×</button>\n\n          <img\n            class="site-dialog-logo"\n            src="${asset("assets/icons/icon-192.png")}"\n            alt=""\n            width="72"\n            height="72"\n          />\n\n          <h2>Add Nanny-Delvin to your phone</h2>\n\n          <p>\n            In Safari, tap the Share button and choose\n            <strong>Add to Home Screen</strong>.\n          </p>\n\n          <button class="button site-dialog-done" type="button">\n            Done\n          </button>\n        </div>\n      `;\n\n      const close = () => {\n        if (typeof dialog.close === "function") {\n          dialog.close();\n        } else {\n          dialog.removeAttribute("open");\n        }\n      };\n\n      dialog\n        .querySelector(".site-dialog-close")\n        .addEventListener("click", close);\n\n      dialog\n        .querySelector(".site-dialog-done")\n        .addEventListener("click", close);\n\n      dialog.addEventListener("click", (event) => {\n        if (event.target === dialog) close();\n      });\n\n      document.body.appendChild(dialog);\n    }\n\n    if (typeof dialog.showModal === "function") {\n      dialog.showModal();\n    } else {\n      dialog.setAttribute("open", "");\n    }\n  }\n\n  async function sharePage() {\n    const data = {\n      title: document.title,\n      text: pageDescription(),\n      url: window.location.href\n    };\n\n    try {\n      if (navigator.share) {\n        await navigator.share(data);\n        return;\n      }\n\n      if (navigator.clipboard && window.isSecureContext) {\n        await navigator.clipboard.writeText(data.url);\n        showToast("Page link copied.");\n        return;\n      }\n\n      window.prompt("Copy this page link:", data.url);\n    } catch (error) {\n      if (error?.name !== "AbortError") {\n        showToast("Sharing was not completed.");\n      }\n    }\n  }\n\n  async function installSite() {\n    if (isStandalone) {\n      showToast("The site is already installed.");\n      return;\n    }\n\n    if (deferredPrompt) {\n      deferredPrompt.prompt();\n      await deferredPrompt.userChoice;\n      deferredPrompt = null;\n      updateInstallButton();\n      return;\n    }\n\n    if (isIOS) {\n      showIOSInstructions();\n      return;\n    }\n\n    showToast(\n      "Use your browser menu and choose Install app or Add to Home Screen."\n    );\n  }\n\n  function updateInstallButton() {\n    const button = document.querySelector("[data-install-site]");\n    if (!button) return;\n\n    const show =\n      !isStandalone && (Boolean(deferredPrompt) || isIOS);\n\n    button.hidden = !show;\n  }\n\n  function replaceLogoMarks() {\n    document.querySelectorAll(".logo-mark").forEach((mark) => {\n      if (mark.querySelector("img")) return;\n\n      mark.classList.add("logo-mark-image");\n      mark.textContent = "";\n\n      const image = document.createElement("img");\n      image.className = "logo-avatar";\n      image.src = asset("assets/icons/icon-192.png");\n      image.alt = "";\n      image.width = 42;\n      image.height = 42;\n\n      mark.appendChild(image);\n    });\n  }\n\n  function addNavigationTools() {\n    document.querySelectorAll(".nav-links").forEach((navigation) => {\n      if (navigation.querySelector(".site-tools")) return;\n\n      const tools = document.createElement("span");\n      tools.className = "site-tools";\n\n      const share = document.createElement("button");\n      share.type = "button";\n      share.className = "site-tool-button";\n      share.title = "Share this page";\n      share.setAttribute("aria-label", "Share this page");\n      share.innerHTML = shareIcon();\n      share.addEventListener("click", sharePage);\n\n      const install = document.createElement("button");\n      install.type = "button";\n      install.className = "site-tool-button";\n      install.title = "Install this website";\n      install.setAttribute("aria-label", "Install this website");\n      install.setAttribute("data-install-site", "");\n      install.hidden = true;\n      install.innerHTML = installIcon();\n      install.addEventListener("click", installSite);\n\n      tools.append(share, install);\n      navigation.appendChild(tools);\n    });\n\n    updateInstallButton();\n  }\n\n  function registerServiceWorker() {\n    const allowed =\n      window.location.protocol === "https:" ||\n      ["localhost", "127.0.0.1"].includes(window.location.hostname);\n\n    if (!allowed || !("serviceWorker" in navigator)) return;\n\n    const workerUrl = new URL("sw.js", siteRoot);\n\n    navigator.serviceWorker\n      .register(workerUrl, { scope: siteRoot.pathname })\n      .catch((error) => {\n        console.warn("Service worker registration failed:", error);\n      });\n  }\n\n  window.addEventListener("beforeinstallprompt", (event) => {\n    event.preventDefault();\n    deferredPrompt = event;\n    updateInstallButton();\n  });\n\n  window.addEventListener("appinstalled", () => {\n    deferredPrompt = null;\n    updateInstallButton();\n    showToast("Nanny-Delvin was added to this device.");\n  });\n\n  document.addEventListener("DOMContentLoaded", () => {\n    replaceLogoMarks();\n    addNavigationTools();\n    registerServiceWorker();\n  });\n})();\n'
SITE_TOOLS_CSS = '/* NDRT logo, sharing, install and footer additions */\n\n.logo-mark.logo-mark-image {\n  overflow: hidden;\n  padding: 0.08rem;\n  background: #ffffff;\n  border: 1px solid rgba(15, 94, 70, 0.12);\n}\n\n.logo-avatar {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  border-radius: 999px;\n}\n\n.site-tools {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n}\n\n.site-tool-button {\n  width: 2.45rem;\n  height: 2.45rem;\n  display: inline-grid;\n  place-items: center;\n  flex: 0 0 auto;\n  border: 1px solid rgba(15, 94, 70, 0.16);\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.82);\n  color: var(--brand);\n  cursor: pointer;\n  transition:\n    transform var(--transition),\n    background var(--transition),\n    border-color var(--transition);\n}\n\n.site-tool-button:hover {\n  transform: translateY(-1px);\n  background: var(--accent);\n  border-color: rgba(15, 94, 70, 0.28);\n}\n\n.site-tool-button:focus-visible {\n  outline: 3px solid rgba(121, 181, 142, 0.42);\n  outline-offset: 2px;\n}\n\n.site-tool-button svg {\n  width: 1.15rem;\n  height: 1.15rem;\n  fill: currentColor;\n}\n\n.site-tool-button[hidden] {\n  display: none !important;\n}\n\n.site-toast {\n  position: fixed;\n  left: 50%;\n  bottom: 1.25rem;\n  z-index: 1000;\n  max-width: min(90vw, 34rem);\n  padding: 0.8rem 1rem;\n  border-radius: 999px;\n  background: #16342a;\n  color: #ffffff;\n  box-shadow: 0 16px 40px rgba(16, 48, 38, 0.22);\n  opacity: 0;\n  transform: translate(-50%, 1rem);\n  pointer-events: none;\n  transition: opacity 0.2s ease, transform 0.2s ease;\n}\n\n.site-toast.is-visible {\n  opacity: 1;\n  transform: translate(-50%, 0);\n}\n\n.site-dialog {\n  width: min(calc(100% - 2rem), 30rem);\n  padding: 0;\n  border: 0;\n  border-radius: 24px;\n  color: var(--text);\n  background: var(--surface);\n  box-shadow: 0 28px 80px rgba(16, 48, 38, 0.28);\n}\n\n.site-dialog::backdrop {\n  background: rgba(11, 35, 28, 0.48);\n  backdrop-filter: blur(4px);\n}\n\n.site-dialog-inner {\n  position: relative;\n  padding: 2rem;\n  text-align: center;\n}\n\n.site-dialog-inner h2 {\n  margin: 0.9rem 0 0.7rem;\n  color: var(--brand);\n}\n\n.site-dialog-logo {\n  width: 72px;\n  height: 72px;\n  margin: 0 auto;\n  border-radius: 999px;\n}\n\n.site-dialog-close {\n  position: absolute;\n  top: 0.65rem;\n  right: 0.8rem;\n  width: 2.2rem;\n  height: 2.2rem;\n  border: 0;\n  border-radius: 999px;\n  background: transparent;\n  color: var(--muted);\n  font-size: 1.8rem;\n  line-height: 1;\n  cursor: pointer;\n}\n\n.site-dialog-done {\n  margin-top: 0.65rem;\n}\n\n.site-footer .footer-grid {\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n}\n\n.footer-meta {\n  grid-column: 1 / -1;\n  padding-top: 1.4rem;\n  margin-top: 0.25rem;\n  border-top: 1px solid var(--border);\n  color: var(--muted);\n  font-size: 0.92rem;\n}\n\n.footer-meta p {\n  margin: 0.35rem 0;\n}\n\n.site-footer a:hover,\n.site-footer a:focus-visible {\n  color: var(--brand);\n  text-decoration: underline;\n}\n\n@media (max-width: 760px) {\n  .site-footer .footer-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .footer-meta {\n    grid-column: 1;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .site-tool-button,\n  .site-toast {\n    transition: none;\n  }\n}\n'


def arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Add the NDRT avatar, native page sharing, install support "
            "and a standard Zenodo footer."
        )
    )
    parser.add_argument(
        "--root",
        type=Path,
        default=Path.cwd(),
        help="Website repository root. Default: current directory.",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Report changes without writing files.",
    )
    return parser.parse_args()


def verify_root(root: Path) -> None:
    missing = [
        path
        for path in (root / "index.html", root / "assets")
        if not path.exists()
    ]

    if missing:
        rendered = ", ".join(str(path) for path in missing)
        raise SystemExit(
            "Run this from the NDRT website repository root. "
            f"Missing: {rendered}"
        )


def relative_prefix(html_file: Path, root: Path) -> str:
    parent = html_file.relative_to(root).parent
    return "../" * len(parent.parts)


def feature_head(prefix: str) -> str:
    return f"""{HEAD_START}
  <meta name="theme-color" content="#0F5E46" />
  <meta name="apple-mobile-web-app-capable" content="yes" />
  <meta name="apple-mobile-web-app-status-bar-style" content="default" />
  <meta name="apple-mobile-web-app-title" content="Nanny-Delvin" />
  <link rel="manifest" href="{prefix}manifest.webmanifest" />
  <link
    rel="icon"
    type="image/png"
    sizes="32x32"
    href="{prefix}assets/icons/favicon-32.png"
  />
  <link
    rel="apple-touch-icon"
    href="{prefix}assets/icons/apple-touch-icon.png"
  />
  <link
    rel="stylesheet"
    href="{prefix}assets/css/site-tools.css"
  />
  <script
    defer
    src="{prefix}assets/js/site-tools.js"
  ></script>
{HEAD_END}"""


