def replace_marked(
    text: str,
    start: str,
    end: str,
    replacement: str,
) -> str:
    pattern = re.compile(
        re.escape(start) + r".*?" + re.escape(end),
        flags=re.DOTALL,
    )
    return pattern.sub(replacement, text, count=1)


def patch_head(text: str, prefix: str) -> tuple[str, bool]:
    block = feature_head(prefix)

    if HEAD_START in text and HEAD_END in text:
        changed = replace_marked(
            text,
            HEAD_START,
            HEAD_END,
            block,
        )
        return changed, changed != text

    match = re.search(r"</head\s*>", text, flags=re.IGNORECASE)
    if not match:
        return text, False

    changed = (
        text[: match.start()]
        + "\n"
        + block
        + "\n"
        + text[match.start() :]
    )
    return changed, True


def patch_footer(text: str, prefix: str) -> tuple[str, bool]:
    footer = standard_footer(prefix)

    pattern = re.compile(
        r"<footer\b[^>]*>.*?</footer\s*>",
        flags=re.IGNORECASE | re.DOTALL,
    )

    if pattern.search(text):
        changed = pattern.sub(footer, text, count=1)
        return changed, changed != text

    match = re.search(r"</body\s*>", text, flags=re.IGNORECASE)
    if not match:
        return text, False

    changed = (
        text[: match.start()]
        + "\n"
        + footer
        + "\n"
        + text[match.start() :]
    )
    return changed, True


def html_pages(root: Path) -> list[Path]:
    pages: list[Path] = []

    for path in root.rglob("*.html"):
        parts = set(path.relative_to(root).parts)
        if parts & IGNORED_PARTS:
            continue
        pages.append(path)

    return sorted(pages)


def backup(
    source: Path,
    root: Path,
    backup_root: Path,
) -> None:
    if not source.exists():
        return

    destination = backup_root / source.relative_to(root)
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, destination)


def write_text_file(
    destination: Path,
    content: str,
    root: Path,
    backup_root: Path,
    dry_run: bool,
) -> None:
    if dry_run:
        return

    backup(destination, root, backup_root)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(content, encoding="utf-8")


def write_binary_file(
    destination: Path,
    encoded: str,
    root: Path,
    backup_root: Path,
    dry_run: bool,
) -> None:
    if dry_run:
        return

    backup(destination, root, backup_root)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_bytes(base64.b64decode(encoded))


def update_gitignore(
    root: Path,
    backup_root: Path,
    dry_run: bool,
) -> bool:
    path = root / ".gitignore"
    entry = ".ndrt_feature_backup/"

    existing = path.read_text(encoding="utf-8") if path.exists() else ""
    lines = {line.strip() for line in existing.splitlines()}

    if entry in lines:
        return False

    if dry_run:
        return True

    backup(path, root, backup_root)
    separator = "" if not existing or existing.endswith("\n") else "\n"
    path.write_text(
        existing + separator + entry + "\n",
        encoding="utf-8",
    )
    return True


def main() -> int:
    args = arguments()
    root = args.root.expanduser().resolve()

    verify_root(root)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = (
        root
        / ".ndrt_feature_backup"
        / timestamp
    )

    changed_pages: list[str] = []

    for page in html_pages(root):
        original = page.read_text(encoding="utf-8")
        prefix = relative_prefix(page, root)

        updated, head_changed = patch_head(original, prefix)
        updated, footer_changed = patch_footer(updated, prefix)

        if not (head_changed or footer_changed):
            continue

        changed_pages.append(str(page.relative_to(root)))

        if not args.dry_run:
            backup(page, root, backup_root)
            page.write_text(updated, encoding="utf-8")

    text_files = {
        root / "manifest.webmanifest": MANIFEST_TEXT,
        root / "sw.js": SERVICE_WORKER_TEXT,
        root / "assets" / "js" / "site-tools.js": SITE_TOOLS_JS,
        root / "assets" / "css" / "site-tools.css": SITE_TOOLS_CSS,
    }

    for destination, content in text_files.items():
        write_text_file(
            destination,
            content,
            root,
            backup_root,
            args.dry_run,
        )

    for filename, encoded in ICON_DATA.items():
        write_binary_file(
            root / "assets" / "icons" / filename,
            encoded,
            root,
            backup_root,
            args.dry_run,
        )

    gitignore_changed = update_gitignore(
        root,
        backup_root,
        args.dry_run,
    )

    mode = "DRY RUN" if args.dry_run else "COMPLETE"

    print()
    print(f"NDRT feature installer: {mode}")
    print(f"Repository: {root}")
    print(f"HTML pages changed: {len(changed_pages)}")

    for page in changed_pages:
        print(f"  {page}")

    print("Files installed or refreshed:")
    for path in text_files:
        print(f"  {path.relative_to(root)}")
    for filename in ICON_DATA:
        print(f"  assets/icons/{filename}")

    if gitignore_changed:
        print("  .gitignore")

    if args.dry_run:
        print()
        print("No files were written.")
        print("Run again without --dry-run to apply the changes.")
    else:
        print()
        print(f"Backup created at: {backup_root}")
        print()
        print("Review locally with:")
        print("  python3 -m http.server 8000")
        print()
        print("Then open:")
        print("  http://localhost:8000/")
        print()
        print("Inspect before committing:")
        print("  git status")
        print("  git diff")

    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        print("\nCancelled.", file=sys.stderr)
        raise SystemExit(130)
